/* Thin minimal range slider. Native track + custom thumb; the pseudo-elements
   can't be expressed with utility classes, so they ship as plain CSS. */
.chrome-range {
  -webkit-appearance: none;
  appearance: none;
  width: 100%;
  height: 2px;
  background: rgba(255, 255, 255, 0.15);
  outline: none;
  cursor: pointer;
}
.chrome-range::-webkit-slider-runnable-track {
  height: 2px;
  background: rgba(255, 255, 255, 0.15);
}
.chrome-range::-moz-range-track {
  height: 2px;
  background: rgba(255, 255, 255, 0.15);
  border: none;
}
.chrome-range::-webkit-slider-thumb {
  -webkit-appearance: none;
  appearance: none;
  width: 12px;
  height: 12px;
  margin-top: -5px;
  background: #fff;
  border: 1px solid rgba(255, 255, 255, 0.8);
  cursor: pointer;
  transition: transform 0.15s ease, background 0.15s ease;
}
.chrome-range::-moz-range-thumb {
  width: 12px;
  height: 12px;
  background: #fff;
  border: 1px solid rgba(255, 255, 255, 0.8);
  cursor: pointer;
  transition: transform 0.15s ease, background 0.15s ease;
}
.chrome-range::-webkit-slider-thumb:hover {
  transform: scale(1.2);
}
.chrome-range::-moz-range-thumb:hover {
  transform: scale(1.2);
}
.chrome-range:disabled {
  opacity: 0.5;
  cursor: not-allowed;
}
